import {cabinet,rect,circle,text,ring,line,clamp} from './cabinet.js';
export const golfCourses=[{ball:[180,386],hole:[180,90],walls:[]},{ball:[80,386],hole:[275,88],walls:[[16,230,224,18]]},{ball:[280,385],hole:[72,94],walls:[[120,210,224,18]]},{ball:[180,390],hole:[180,85],walls:[[95,225,170,22]]},{ball:[65,385],hole:[292,89],walls:[[16,265,195,18],[155,155,189,18]]}];
export function bounceGolf(ball,wall){const [x,y,w,h]=wall,r=7,nx=clamp(ball.x,x,x+w),ny=clamp(ball.y,y,y+h),dx=ball.x-nx,dy=ball.y-ny,dist=Math.hypot(dx,dy);if(dist>=r)return false;if(dist>0){const ux=dx/dist,uy=dy/dist,dot=ball.vx*ux+ball.vy*uy;ball.x=nx+ux*r;ball.y=ny+uy*r;if(dot<0){ball.vx-=1.8*dot*ux;ball.vy-=1.8*dot*uy;}}else{ball.y=y-r;ball.vy=-Math.abs(ball.vy)*.8;}return true;}
export function createGolf(mount,api){const q=cabinet(mount,api,{accent:'#aee57e'}),c=q.c;let hole=0,strokes=0,ball,drag=null,end=null,angle=-Math.PI/2,power=320,delay=0,trail=[];
 function setup(){const course=golfCourses[hole];ball={x:course.ball[0],y:course.ball[1],vx:0,vy:0};drag=null;end=null;trail=[];delay=0;angle=Math.atan2(course.hole[1]-ball.y,course.hole[0]-ball.x);}
 const moving=()=>Math.hypot(ball.vx,ball.vy)>2;
 function shoot(){if(!q.active||moving()||delay>0)return;strokes++;ball.vx=Math.cos(angle)*power;ball.vy=Math.sin(angle)*power;q.sound('putt');drag=null;}
 function aim(p){end=p;const dx=drag.x-p.x,dy=drag.y-p.y;if(Math.hypot(dx,dy)>4){angle=Math.atan2(dy,dx);power=clamp(Math.hypot(dx,dy)*4,40,480);}}
 setup();return {start(){hole=0;strokes=0;power=320;q.start();setup();},pointerDown(p){if(!moving()&&delay===0){drag=q.local(p);end=drag;}},pointerMove(p){if(drag)aim(q.local(p));},pointerUp(p){if(!drag)return;aim(q.local(p));const distance=Math.hypot(end.x-drag.x,end.y-drag.y);drag=null;if(distance>8)shoot();},cancel(){drag=null;},direction(d){if(d==='left')angle-=.08;if(d==='right')angle+=.08;if(d==='up')power=clamp(power+25,40,480);if(d==='down')power=clamp(power-25,40,480);},action:shoot,tick(dt){q.frame(dt,dt=>{if(delay>0){delay-=dt;if(delay<=0){hole++;setup();}return;}if(!moving())return;for(let n=0;n<4;n++){ball.x+=ball.vx*dt/4;ball.y+=ball.vy*dt/4;let bounced=false;if(ball.x<23||ball.x>337){ball.x=clamp(ball.x,23,337);ball.vx*=-.8;bounced=true;}if(ball.y<51||ball.y>429){ball.y=clamp(ball.y,51,429);ball.vy*=-.8;bounced=true;}for(const w of golfCourses[hole].walls)if(bounceGolf(ball,w))bounced=true;if(bounced)q.sound('bounce');const h=golfCourses[hole].hole;if(Math.hypot(ball.x-h[0],ball.y-h[1])<12&&Math.hypot(ball.vx,ball.vy)<230){ball.x=h[0];ball.y=h[1];ball.vx=ball.vy=0;q.add(100+Math.max(0,20-strokes)*5);q.burst(ball.x,ball.y);q.sound('cup');q.say('IN THE CUP!');if(hole===4){q.finish('A lovely little round.',`Five holes in ${strokes} strokes.`,true);}else delay=1;return;}}
  const friction=Math.exp(-1.15*dt);ball.vx*=friction;ball.vy*=friction;trail.push({x:ball.x,y:ball.y});trail=trail.slice(-18);if(Math.hypot(ball.vx,ball.vy)<9){ball.vx=ball.vy=0;if(strokes>=20)q.finish('Clubhouse time.',`${hole} holes completed in 20 strokes. Try a softer touch.`);}
 },()=>{q.header(`HOLE ${hole+1}/5`,`${20-strokes} STROKES LEFT`);rect(c,12,40,336,400,'#29473b',18);for(let y=48;y<436;y+=48)rect(c,17,y,326,24,'#ffffff04',4);for(const w of golfCourses[hole].walls){rect(c,w[0],w[1]+4,w[2],w[3],'#0f231d',5);rect(c,...w,'#cad7a0',5);}const h=golfCourses[hole].hole;ring(c,h[0],h[1],17,'#b1e07955');circle(c,h[0],h[1],11,'#0a201a');text(c,hole+1,h[0]+22,h[1]-12,14,'#d1e8a8',700);trail.forEach((p,i)=>circle(c,p.x,p.y,2,`rgba(222,255,213,${i/50})`));if(!moving()&&!delay){for(let n=1;n<=12;n++)circle(c,ball.x+Math.cos(angle)*n*power/30,ball.y+Math.sin(angle)*n*power/30,1.5,'#d4e8ba99');}if(!delay){circle(c,ball.x,ball.y+2,8,'#071c2166');circle(c,ball.x,ball.y,7,'#f8ffe8');}q.footer(drag?`POWER ${Math.round(power/4.8)}% · release to putt`:'Pull back anywhere. Release to putt.');});},destroy:q.destroy};}
